		[5148] = {
		   ["objective"] = "Принесите дикарский кожаный жилет и дикарский кожаный шлем Сех'Джибу в Тернистой долине.$B$BВыполнив это задание, вы станете кожевником школы традиций предков.$B$BТакже вы лишитесь возможности изучать кожевничество школы Дракона и школы силы стихий; убедитесь, что избрали верный путь, прежде чем выполнять задание.";
		   ["name"] = "Кожевничество: традиции предков";
