		   ["objective"] = "Überbringt dem Erzdruiden Fandral Hirschhaupt in Darnassus den Kristall von Zin-Malor.";
		};
		[5301] = {
		   ["name"] = "Die Kunst des Rüstungsschmiedes";
		   ["objective"] = "Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Okothos bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte.";
		};
		[5381] = {
		   ["name"] = "Hand von Iruxos";
		   ["objective"] = "Holt den Dämonenkasten aus der Festung Donneraxt und kehrt damit zu Taiga Klugmähne nach Schattenflucht zurück.";
		};
		[5461] = {
		   ["name"] = "Der Mensch Ras Frostraunen";
		   ["objective"] = "Reist in das Arathihochland zu den Ruinen von Stromgarde. Durchsucht Stromgarde nach einem Andenken der Erinnerung. Wenn Ihr einen solchen Gegenstand findet, kehrt mit ihm zu Magistrat Marduk zurück.";
		};
		[2747] = {
		   ["name"] = "Ein außergewöhnliches Ei";
		};
		[2755] = {
		   ["name"] = "Freude der Omoshs";
		   ["objective"] = "Seht zu und lernt den Freudentanz der Omoshs.";
		};
		[2763] = {
		   ["name"] = "Die Kunst der Magieerfüllung";
		   ["objective"] = "Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 4 Citrine.";
		};
		[5541] = {
		   ["name"] = "Munition für Schlingerschuss";
		   ["objective"] = "Bringt Schlingerschuss' Munition zu Hegnar Schlingerschuss in Dun Morogh.";
		};
		[5621] = {
		   ["objective"] = "Sucht die Schildwache Shaya und heilt ihre Wunden mithilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Laurna Morgenglanz in Dolanaar zurück.";
		   ["name"] = "Gewänder des Mondes";
		};
		[5637] = {
		   ["name"] = "Verzweifeltes Gebet";
		   ["objective"] = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.";
		};
		[2843] = {
		   ["name"] = "Gnomer-weeeeg!";
		   ["objective"] = "Wartet, bis Scooty den Goblintransponder kalibriert hat.";
		};
		[2851] = {
		   ["name"] = "Wildlederstiefel";
		   ["objective"] = "Bringt Pratt McGrubben in der Mondfederfeste 2 Hosen des Nachtschleichers, 2 Stiefel des Nachtschleichers und 2 Wildranken.";
		};
		[2859] = {
		   ["name"] = "Wildledergamaschen";
		   ["objective"] = "Bringt Jangdor Flinkschreiter im Camp Mojache 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken.";
		};
		[2867] = {
		   ["name"] = "Kehrt zur Mondfederfeste zurück";
		   ["objective"] = "Kehrt zu Shandris Mondfeder in der Mondfederfeste zurück und berichtet von Euren Entdeckungen.";
		};
		[2875] = {
		   ["name"] = "GESUCHT: Andre Feuerbart";
		   ["objective"] = "Bringt Sicherheitschef Bilgenritzel beim Dampfdruckpier Andres Kopf.";
		};
		[5781] = {
		   ["name"] = "Von vergessenen Erinnerungen";
		   ["objective"] = "Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.";
		};
		[5845] = {
		   ["name"] = "Von verlorener Ehre";
		   ["objective"] = "Reist ins Nordtal im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.";
		};
		[5861] = {
		   ["name"] = "Myranda suchen";
		   ["objective"] = "Begebt Euch zu Uthers Grabmal in den Südlichen Pestländern. Zeigt Myranda der Vettel Tirions Geschenk.";
		};
		[2939] = {
		   ["name"] = "Auf der Suche nach Wissen";
		   ["objective"] = "Sprecht mit Daryn Leuchtwind im Dorf Rut'theran.";
		};
		[5893] = {
		   ["name"] = "Vorräte der Eisbeißermine";
		   ["objective"] = "Bringt 10 Vorräte der Eisbeißermine zum Rüstmeister der Horde in die Burg Frostwolf.";
		};
		[2963] = {
		   ["name"] = "Omen von Uldum";
		   ["objective"] = "Sprecht mit Historiker Karnik in der Halle der Forscher in Eisenschmiede.";
		};
		[5941] = {
		   ["name"] = "Rückkehr zu Chromie";
		   ["objective"] = "Bringt das Reliktbündel zu Chromie nach Andorhal.";
		};
		[2979] = {
		   ["name"] = "Dunkle Zeremonie";
		   ["objective"] = "Rok Orhan im Camp Mojache will, dass Ihr eine Gordunnikugel findet.";
		};
		[2987] = {
		   ["name"] = "Gordunnikobalt";
		   ["objective"] = "Orwin Gizzmick im Camp Mojache will 12 Proben Gordunnikobalt.";
		};
		[2995] = {
		   ["objective"] = "Verbrennt die Hochtalaufzeichnungen, Hochtalberichte und Hochtalnotizen.";
		   ["name"] = "Nachrichtenwege";
		};
		[6021] = {
		   ["name"] = "Zaeldarr der Ausgestoßene";
		   ["objective"] = "Bringt Zaeldarrs Kopf zu Verwalter Alen in der Kapelle des Hoffnungsvollen Lichts.";
		};
		[6069] = {
		   ["name"] = "Der Weg des Jägers";
		   ["objective"] = "Sprecht mit Thotar in Klingenhügel in Durotar.";
		};
		[6085] = {
		   ["name"] = "Die Zähmung der Bestie";
		   ["objective"] = "Benutzt die Zähmrute, um einen Eisklauenbären zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildherz in Kharanos.";
		};
		[6101] = {
		   ["name"] = "Die Zähmung der Bestie";
		   ["objective"] = "Benutzt die Zähmerrute, um einen pirschenden Nachtsäbler zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.";
		};
		[6133] = {
		   ["name"] = "Das Ersuchen des Waldläuferlords";
		   ["objective"] = "Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Registratur von Quel'Thalas zurück. Der Gegenstand befindet sich irgendwo in der Jagdhütte von Quel'Lithien.$B$BAußerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten.";
		};
		[8201] = {
		   ["name"] = "Die Schädelsammlung";
		   ["objective"] = "Reiht die Köpfe der 5 Kanalisierer auf der heiligen Kordel aneinander. Bringt dann die Trollschädelsammlung zu Exzhal auf der Insel Yojamba.";
		};
		[3083] = {
		   ["name"] = "Verschlüsselte Schrifttafel";
		   ["objective"] = "Lest die verschlüsselte Schrifttafel und sprecht mit Rwag im Tal der Prüfungen.";
		};
		[3091] = {
		   ["name"] = "Einfache Notiz";
		   ["objective"] = "Lest die einfache Nachricht und sprecht mit Harutt Donnerhorn im Camp Narache.";
		};
		[8297] = {
		   ["name"] = "Die Ressourcen des Arathibeckens";
		   ["objective"] = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Unteroffizier Maclear in der Zuflucht.";
		};
		[3107] = {
		   ["name"] = "Geweihte Rune";
		   ["objective"] = "Lest die geweihte Rune und sprecht mit Bromos Grummler in Ambossar.";
		};
		[8361] = {
		   ["name"] = "Abyssische Kontakte";
		   ["objective"] = "Bor Wildmähne auf Burg Cenarius in Silithus möchte, dass Ihr einen abyssischen Templer vernichtet und ihm dessen abyssisches Wappen als Beweis für Eure Tat bringt.";
		};
		[3123] = {
		   ["name"] = "Das Gefäß wird getestet";
		   ["objective"] = "Tötet 10 Eisenfellbären oder Langzahnläufer und benutzt dann das Gefäß für Bestienmuisek, um die gefallenen Tiere zu schrumpfen und einzufangen.$B$BBringt anschließend 10 Einheiten Bestienmuisek und das Gefäß für Bestienmuisek zu Hexendoktor Uzer'i in Feralas.";
		};
		[8425] = {
		   ["name"] = "Voodoofedern";
		   ["objective"] = "Bringt die Voodoofedern der Trolle im Versunkenen Tempel zu dem gefallenen Helden der Horde.";
		};
		[8521] = {
		   ["name"] = "Die Allianz braucht mehr Seidenverbände!";
		   ["objective"] = "Bringt 20 Seidenverbände zu Schwester Steinfeld beim Landeplatz in Dun Morogh.";
		};
		[8553] = {
		   ["name"] = "Der Entersäbel des Kapitäns";
		   ["objective"] = "Sprecht mit Knirpsens.";
		};
		[6341] = {
		   ["name"] = "Auf nach Darnassus";
		   ["objective"] = "Sprecht mit Fidelio, um einen Flug nach Darnassus zu erstehen, und bringt dann die Rezeptsammlung von Dolanaar zu Schwester Aquinne in Darnassus.";
		};
		[8649] = {
		   ["name"] = "Urahne Sturmbraue";
		};
		[8681] = {
		   ["name"] = "Urahne Donnerhorn";
		};
		[8713] = {
		   ["name"] = "Urahnin Sternensang";
		};
		[6421] = {
		   ["name"] = "Steinschlagklamm";
		   ["objective"] = "Erkundet die Tiefen der Höhle in der Steinschlagklamm und bringt Mor'rogal in Sonnenfels 10 Resonitkristalle, damit er sie untersuchen kann.";
		};
		[8777] = {
		   ["name"] = "Ziel: Einbuddler des Regalschwarms";
		   ["objective"] = "Tötet 30 Einbuddler des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz XI, um diese Aufgabe abschließen zu können.";
		};
		[8809] = {
		   ["name"] = "Besondere Materialien";
		   ["objective"] = "Bringt Vargus auf Burg Cenarius in Silithus 2 verzauberte Thoriumbarren und 2 Einheiten verzaubertes Leder. Ihr benötigt auch Logistikeinsatz IX, um diese Aufgabe abschließen zu können.";
		};
		[8841] = {
		   ["name"] = "Zehn Belobigungsabzeichen";
		};
		[8873] = {
		   ["name"] = "Das Mondfest";
		   ["objective"] = "Sprecht mit der Botin des Mondfests im Tal der Weisheit in Orgrimmar. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.";
		};
		[8905] = {
		   ["name"] = "Ein aufrichtiges Angebot";
		   ["objective"] = "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Wildherzens zu Deliana in Eisenschmiede.";
		};
		[8937] = {
		   ["name"] = "Die angemessene Entlohnung";
		   ["objective"] = "Bringt Deliana in Eisenschmiede einen Gürtel der Ehre und ein Paar Stulpen der Ehre.";
		};
		[8969] = {
		   ["name"] = "Das linke Stück von Lord Valthalaks Amulett";
		   ["objective"] = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Kormok zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.";
		};
		[9001] = {
		   ["name"] = "Das Beste gibt's zum Schluss";
		   ["objective"] = "Gebt Deliana Eure Krone des Magisters und Eure Roben des Magisters.";
		};
		[9033] = {
		   ["name"] = "Echo des Krieges";
		   ["objective"] = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte, dass Ihr 5 lebende Monstrositäten, 5 Steinhautgargoyles, 8 Hauptmänner der Todesritter und 3 Giftpirscher tötet.";
		};
		[6581] = {
		   ["name"] = "Sägeblätter des Kriegshymnenklans";
		};
		[9097] = {
		   ["name"] = "Frostfeuerreif";
		   ["objective"] = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Frostfeuerreif anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 entweihten Reif, 15 kampfzerschlissene Stoffstücke, 3 Einheiten Mondstoff und 3 Nexuskristalle.";
		};
		[9129] = {
		   ["name"] = "Kern der Elemente";
		};
		[6629] = {
		   ["name"] = "Tötet Grundig Finsterwolke";
		   ["objective"] = "Tötet Grundig Finsterwolke und 6 Schläger der Grimmtotem und kehrt dann zu Makaba Flachhuf am südöstlichen Rand des Steinkrallengebirges zurück.";
		};
		[6645] = {
		   ["name"] = "Gunst der Bruderschaft, Kernleder";
		};
		[9225] = {
		   ["name"] = "Epische Kampfausrüstung - Respekt der Dämmerung";
		   ["objective"] = "Für 45 Insignien der Dämmerung und 45 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.";
		};
		[9257] = {
		   ["name"] = "Atiesh, Hohestab des Wächters";
		   ["objective"] = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.";
		};
		[3363] = {
		   ["name"] = "Verderbte Liedblume";
		};
		[6741] = {
		   ["name"] = "Mehr Beute!";
		};
		[3379] = {
		   ["name"] = "Schattenweber";
		   ["objective"] = "Tötet die Gruppe der Schattenseidewilderer, die in der Sengenden Schlucht umherstreifen. Nilith hat Grund zu der Annahme, dass es fünf von ihnen gibt, die ausgeschaltet werden müssen.";
		};
		[6805] = {
		   ["name"] = "Stürmer und Rumpler";
		   ["objective"] = "Tötet 15 Staubstürmer und 15 Wüstenrumpler und kehrt dann zu Fürst Hydraxis in Azshara zurück.";
		};
		[6821] = {
		   ["name"] = "Auge des Glutsehers";
		   ["objective"] = "Bringt das Auge des Glutsehers zu Fürst Hydraxis in Azshara.";
		};
		[3443] = {
		   ["name"] = "Das Schmieden des Schafts";
		   ["objective"] = "Bringt 8 mit Thorium beschichtete Dolche zu Kalaran Windklinge.";
		};
		[6901] = {
		   ["name"] = "Startet den Angriff!";
		};
		[3483] = {
		   ["name"] = "Signal zum Abholen";
		};
		[6981] = {
		   ["name"] = "Der leuchtende Splitter";
		   ["objective"] = "Begebt Euch nach Ratschet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann.$B$BLiefert dann den Splitter ab, wie Ihr angewiesen wurdet.";
		};
		[3507] = {
		   ["name"] = "Verraten";
		   ["objective"] = "Sprecht mit Belgrom Felshammer in Orgrimmar.";
		};
		[7029] = {
		   ["objective"] = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.$B$BBenutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxiousspross herausgezwungen wird.$B$BHeilt 8 Pflanzen, indem Ihr diesen Noxxiousspross tötet und kehrt dann zu Vark Schlachtnarbe in Schattenflucht zurück.";
		   ["name"] = "Schlangenzunges Verderbnis";
		};
		[7045] = {
		   ["name"] = "Ein Dankeschön von Kokelwälder!";
		   ["objective"] = "Sprecht mit Altvater Winter in Eisenschmiede.";
		};
		[7061] = {
		   ["name"] = "Das Winterhauchfest";
		   ["objective"] = "Ihr könnt gern das Buch 'Das Winterhauchfest' lesen, um mehr über diesen Feiertag zu erfahren. Wenn Ihr das Buch gelesen habt, bringt es zu Baine Bluthuf in Donnerfels.";
		};
		[3563] = {
		   ["name"] = "Jes'rimons Bezahlung für Jediga";
		   ["objective"] = "Bringt Jes'rimons Notiz zu Jediga in Azshara.";
		};
		[7141] = {
		   ["name"] = "Die Schlacht um Alterac";
		   ["objective"] = "Betretet das Alteractal, bezwingt den Hordegeneral Drek'thar und kehrt dann zu Ausgrabungsleiter Steinhauer im Alteracgebirge zurück.";
		};
		[3627] = {
		   ["name"] = "Das zerbrochene Amulett vereinen";
		   ["objective"] = "Tötet Grol den Zerstörer, Lady Sevine und Erzmagier Allistarj. Nehmt das Amulett von Grol, das Amulett von Sevine und das Amulett von Allistarj von ihren Leichen.$B$BDenkt daran, Eure Verzauberte Azsharitteufelswaffe zu BENUTZEN, um die Triade zu schwächen. Auf eine andere Weise können sie nicht getötet werden - aber verwendet sie weise...";
		};
		[3635] = {
		   ["name"] = "Gnomeningenieurskunst";
		   ["objective"] = "Wenn Ihr mehr über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Glotz Widrikus nach Beutebucht.";
		};
		[3643] = {
		   ["name"] = "Zeigt Eure Arbeit";
		   ["objective"] = "Bringt 6 Mithrilrohre, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Glotz Widrikus in Beutebucht.";
		};
		[7301] = {
		   ["objective"] = "Begebt Euch ins Frostwolfterritorium und sucht nach Schwadronskommandant Slidore, Schwadronskommandant Vipore und Schwadronskommandant Ichman. Meldet Euch bei Kommandant Duffy, sobald Ihr Eure Mission erfüllt habt.";
		   ["name"] = "Gefallene Himmelsstürmer";
		};
		[7365] = {
		   ["name"] = "Hirschhaupts Requiem";
		   ["objective"] = "Ihr wurdet beauftragt gegnerische Trollspieler im Alteractal zu töten.$B$BTötet einen Troll und bringt Athramanis in Dun Baldar etwas Trollmojo der Dunkelspeere.";
		};
		[7381] = {
		   ["name"] = "Korraks Rückkehr";
		   ["objective"] = "Sollte Korrak der Blutrünstige wieder in den Winteraxhöhlen auftauchen, sucht ihn auf und tötet ihn.$B$BBringt Korraks Schädel zu Kriegsmeister Laggrond auf Burg Frostwolf.";
		};
		[7429] = {
		   ["name"] = "Befreit Knot!";
		};
		[7461] = {
		   ["name"] = "Der innere Wahnsinn";
		   ["objective"] = "Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.$B$BBetretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten.$B$BKehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück.";
		};
		[7493] = {
		   ["name"] = "Die Reise beginnt erst";
		};
		[7509] = {
		   ["name"] = "Das Schmieden von Quel'Serrar";
		   ["objective"] = "Bringt Onyxia dazu, ihren Feueratem auf die noch unerhitzte Klinge zu benutzen. Sobald dies geschehen ist, hebt die erhitzte Klinge wieder auf. Doch seid gewarnt, die erhitzte Klinge wird nicht auf ewig erhitzt bleiben - behaltet also die Zeit im Auge.$B$BZuletzt müsst Ihr das Biest töten und die uralte erhitzte Klinge in ihren Leib rammen. Kehrt anschließend zu mir zurück und Quel'Serrar wird Euer sein.";
		};
		[3763] = {
		   ["name"] = "Erzdruide Hirschhaupt helfen";
		   ["objective"] = "Sprecht mit Erzdruide Fandral Hirschhaupt in Darnassus.";
		};
		[7541] = {
		   ["name"] = "Dienst an der Horde";
		};
		[3787] = {
		   ["name"] = "Lebenshands Bitte";
		   ["objective"] = "Sprecht mit Quintis Lebenshand in der Mondfederfeste.";
		};
		[3803] = {
		   ["name"] = "Morgenkorn nach Darnassus";
		};
		[7621] = {
		   ["name"] = "Eine Warnung";
		};
		[7637] = {
		   ["name"] = "Ein Opfer darbieten";
		   ["objective"] = "Reist nach Eisenschmiede und besorgt Euch Hohepriester Rohans Weihrauchschwenker. Eine Spende von 150 Gold wird erforderlich sein, um es zu bekommen.";
		};
		[7653] = {
		   ["name"] = "Imperialer Plattengürtel";
		};
		[3843] = {
		   ["name"] = "Das neueste Mitglied der Familie";
		   ["objective"] = "Bringt Euer empfindliches Grimmlingflitzerei ins Hinterland und sprecht mit Agnar Tiermeister, aber beeilt Euch. Ihr habt nur eine Stunde Zeit, ihn zu finden. Dann stirbt das Jungtier in dem Ei.";
		};
		[7701] = {
		   ["name"] = "GESUCHT: Vorarbeiter Maltorius";
		   ["objective"] = "Tief in der Schlackengrube des Kessels in der Sengenden Schlucht werdet Ihr den verräterischen Dunkeleisenzwerg, Aufseher Maltorius, finden. $B$BTötet den Aufseher Maltorius und nehmt seinen Kopf an Euch. Bringt diesen zum Hauptmann des Ausgucks Lolo Langhieb in der Sengenden Schlucht für eine Belohnung.";
		};
		[7733] = {
		   ["name"] = "Beste Qualität";
		   ["objective"] = "Bringt Pratt McGrubben in der Mondfederfeste 10 Wutschrammyetibälge.";
		};
		[3883] = {
		   ["name"] = "Eine fremdartige Ökologie";
		   ["objective"] = "Verwendet die Kratzphiole, um damit eine Schwarmbauwandprobe von einer der Schwarmbrutstätten der Gorishi im Krater von Un'Goro zu holen. Sucht nach den Kammern mit der hängenden Larvenbrut.$B$BBringt die Schwarmbauwandprobe zu Hol'anyee Marschall im Krater von Un'Goro.";
		};
		[7781] = {
		   ["name"] = "Der Herrscher des Schwarzfels";
		   ["objective"] = "Bringt König Varian Wrynn in Sturmwind den Kopf von Nefarian.";
		};
		[3907] = {
		   ["name"] = "Disharmonie des Feuers";
		   ["objective"] = "Betretet die Schwarzfelstiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Donnerherz.";
		};
		[7829] = {
		   ["name"] = "Jagt die Wilden";
		   ["objective"] = "Jäger Markhor aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr 10 Wilde Eulenbestien tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.$B$BMarkhor erwähnte, dass sich die Eulenbestien in der Wildnis des Hinterlands befinden.";
		};
		[7845] = {
