		[6983] = {
		   ["name"] = "So was Gemeines...";
		   ["objective"] = "Sucht die gestohlenen Leckereien und befreit Metzen das Rentier, nachdem Ihr den monströsen Griesgram besiegt habt. Er verbirgt sich nahe der Eisfellhöhle im Vorgebirge des Hügellandes.";
		};
