		[3628] = {
		   ["name"] = "Ihr seid Rakh'likh, Dämon";
		   ["objective"] = "Vernichtet Razelikh den Entweiher und bringt das abgespaltene Horn des Entweihers zum Gefallenen Helden der Horde. Ihr müsst außerdem den Zauberschutz des Entweihers mit zurückbringen, damit der Gefallene Held ihn zerstören und somit verhindern kann, dass er jemals in die falschen Hände fällt.";
		};
		[3636] = {
