		   ["name"] = "Elementarlederverarbeitung";
		   ["objective"] = "Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Sarah Gerber in die Sengende Schlucht.$B$BWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.$B$BWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.";
		};
		[5160] = {
		   ["name"] = "Die oberste Beschützerin";
		   ["objective"] = "Begebt Euch nach Winterquell und sucht Haleh. Gebt ihr Awbees Schuppe.";
		};
		[5224] = {
		   ["name"] = "Der Kessel des Trostlosen Felds";
		};
		[5384] = {
		   ["name"] = "Kirtonos der Herold";
		   ["objective"] = "Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren.$B$BKämpft tapfer, gebt keinen Fußbreit nach! Vernichtet Kirtonos und kehrt zu Eva Sarkhoff zurück.";
		};
		[5464] = {
		   ["name"] = "Menethils Geschenk";
		   ["objective"] = "Bringt das seelengebundene Andenken zu Leonidas Bartholomäus in den Östlichen Pestländern.";
		};
