		   ["name"] = "Der Funkelmat 5200!";
		   ["objective"] = "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren.";
		};
		[9232] = {
		   ["name"] = "Das Einzige, das ich kann...";
		   ["objective"] = "Handwerker Wilhelm in der Kapelle des Hoffnungsvollen Lichts möchte, dass Ihr ihm 2 gefrorene Runen, 2 Essenzen des Wassers, 2 blaue Saphire und 30 Goldstücke bringt.";
		};
		[9264] = {
		   ["name"] = "Erforscht die Geißel von Donnerfels";
