		   ["name"] = "Das Ausplündern der Plünderer";
		   ["objective"] = "Bringt den Schatz der Südmeerfreibeuter zu Wrenix dem Jämmerlichen in Ratschet. Vergesst nicht, einen R.C.V.K. und Diebeswerkzeug von Wrenixs Elektrodingsda-Apparat zu bringen. Ihr werdet diese Dinge brauchen, um Eure Mission zu beenden.$B$BWenn Ihr von ungewöhnlich feindlichen Papageien angegriffen werdet, benutzt Euren R.C.V.K.!";
		};
		[4809] = {
		   ["name"] = "Hörner der Eiswindschimären";
		   ["objective"] = "Beschafft Euch 8 unbeschädigte Hörner.";
		};
		[4841] = {
		   ["name"] = "Befriedung der Zentauren";
		   ["objective"] = "Tötet 12 Späher der Galak, 10 Zänker der Galak sowie 6 Windjäger der Galak und kehrt dann zu Klippenbehüter Langhorn am Freiwindposten zurück.";
		};
