		   ["objective"] = "Sucht Mankriks Frau und kehrt dann zu ihm in die Siedlung beim Wegekreuz zurück.";
		   ["name"] = "In der Schlacht vermisst";
		};
		[4969] = {
		   ["name"] = "Wissen der Kugel von Orahil";
		   ["objective"] = "Sprecht mit Menara Leerbringer im Brachland.";
		};
