		   ["name"] = "Die Tierwelt leidet auch";
		   ["objective"] = "Tötet 8 kranke Grizzlys und kehrt dann zu Mulgris Tiefenfurt auf dem Trostlosen Feld in den Westlichen Pestländern zurück.";
		};
		[2501] = {
		   ["name"] = "Reagenziensuche im Ödland II";
		   ["objective"] = "Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Ghak Heilsegen in Thelsamar.";
		};
		[5049] = {
		   ["name"] = "Der Jammer des Jeremiah";
		   ["objective"] = "Sucht Jeremiah Payson in Unterstadt und findet heraus, ob er tatsächlich Jeremiah Teufelsstein ist. Wenn er es ist, dann möchte er vielleicht das Paket haben, das Janice Teufelsstein für ihn gepackt hat.";
		};
		[5065] = {
		   ["name"] = "Die verlorenen Schrifttafeln von Mosh'aru";
		   ["objective"] = "Bringt Ausgrabungsleiter Eisenschuh in Tanaris die dritte und vierte Schrifttafel von Mosh'aru.";
		};
