		   ["objective"] = "Bringt einen Voodooglücksbringer des Schamanen zu Oben Zornklaue in den Grabhügel von Ban'ethil.";
		};
		[5097] = {
		   ["objective"] = "Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.$B$BWenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Kommandant Ashlam Ehrenschlag an der Zugwindspitze in den Westlichen Pestländern zurück.";
		   ["name"] = "Turm um Turm";
		};
		[5145] = {
		   ["name"] = "Drachenlederverarbeitung";
		   ["objective"] = "Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Thorkaf Drachenaug im Ödland.$B$BWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.$B$BIhr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.";
		};
		[2581] = {
		   ["name"] = "Kicherfangunterkiefer";
		   ["objective"] = "Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange.";
		};
		[2605] = {
		   ["name"] = "Der durstige Goblin";
		   ["objective"] = "Beschafft Euch eine volle Taudrüse und bringt sie nach Gadgetzan zu Marin Noggenfogger.";
		};
		[5225] = {
		   ["name"] = "Ziel: Gahrrons Trauerfeld";
		   ["objective"] = "Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.";
		};
		[2621] = {
		   ["name"] = "Der Entehrte";
		   ["objective"] = "Sprecht in Steinard in den Sümpfen des Elends mit Zentralenkommandant Ruag.";
		};
		[5305] = {
		   ["name"] = "Süße Beschaulichkeit";
		   ["objective"] = "Begebt Euch nach Stratholme und tötet den purpurroten Hammerschmied. Nehmt die Schürze des purpurroten Hammerschmiedes und kehrt zu Lilith zurück.";
		};
		[2661] = {
		   ["name"] = "Lieferung für Marin";
		   ["objective"] = "Sprinkel möchte, dass Ihr das violette Pulver nach Gadgetzan zu Marin Noggenfogger bringt.";
		};
		[5385] = {
		   ["name"] = "Die Überreste von Trey Lichtschmied";
		   ["objective"] = "Bringt die Überreste von Trey Lichtschmied zu Jessir Mondsichel im Teufelswald.";
		};
		[2701] = {
		   ["name"] = "Helden der Vergangenheit";
		   ["objective"] = "Öffnet die Truhe und nehmt Euch Eure Belohnung.";
		};
		[5465] = {
		   ["name"] = "Seelengebundenes Andenken";
		   ["objective"] = "Kehrt zu Magistrat Marduk in Darrowehr zurück. Zeigt ihm das seelengebundene Andenken.";
		};
		[2741] = {
		   ["name"] = "Der Super-Ei-o-Mat";
		};
		[2749] = {
		   ["name"] = "Ein gewöhnliches Ei";
		};
		[5513] = {
		   ["name"] = "Mäntel der Dämmerung";
		   ["objective"] = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Knackschloss an der Kapelle des Hoffnungsvollen Lichts, Östliche Pestländer.";
		};
		[2765] = {
		   ["name"] = "Schmiedkunstexperte!";
		   ["objective"] = "Fordert Eure Belohnung von Galvan dem Alten ein!";
		};
		[2773] = {
		   ["name"] = "Mithril-Kid";
		   ["objective"] = "Bringt Trenton Lichthammer 2 schwere Mithrilbrustplatten und 1 verschnörkelten Mithrilhandschuh.";
		};
		[2781] = {
		   ["name"] = "GESUCHT: Kalif Skorpidstich";
		   ["objective"] = "Bringt Chefingenieur Bilgenritzel in Gadgetzan den Kopf von Kalif Skorpidstich.";
		};
		[5625] = {
		   ["objective"] = "Sucht den Gebirgsjäger Dolf und heilt seine Wunden mithilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Maxan Anvol in Kharanos zurück.";
		   ["name"] = "Gewänder des Lichts";
		};
		[2821] = {
		   ["name"] = "Das Zeichen der Qualität";
		   ["objective"] = "Bringt Pratt McGrubben in der Mondfederfeste 10 dicke Yetibälge.";
		};
		[5657] = {
		   ["name"] = "Verhexung der Schwäche";
		   ["objective"] = "Sprecht mit Ur'kyo in Orgrimmar.";
		};
		[5673] = {
		   ["name"] = "Elunes Anmut";
		   ["objective"] = "Sprecht mit der Priesterin Alathea in Darnassus.";
		};
		[2845] = {
		   ["name"] = "Streunende Shay";
		   ["objective"] = "Nehmt Shays Glocke aus der Truhe.$B$BBegleitet Shay Laubschleicher zu Felsbeißers Lager.";
		};
		[2853] = {
		   ["name"] = "Meister des Wildleders";
		   ["objective"] = "Gebt Telonis, dem Lederverarbeitungsmeister von Darnassus, Pratts Brief.";
		};
		[5721] = {
		   ["objective"] = "Legt das Reliktbündel auf den Marktplatz von Darroheim.$B$BVerhindert Davil Lichterscheins Tod, bis Horgus stirbt.$B$BVerhindert Hauptmann Rotpfads Tod, bis Rotpfad der Verderbte erscheint.$B$BBesiegt Rotpfad den Verderbten.$B$BSprecht mit dem Geist von Joseph Rotpfad, sobald er auf dem Marktplatz erscheint, und sprecht dann mit Pamela in ihrem Zuhause.";
		   ["name"] = "Die Schlacht um Darroheim";
		};
		[2869] = {
		   ["name"] = "Gegen die Hasskämme";
		   ["objective"] = "Bringt Latronicus Mondspeer in der Mondfederfeste 10 Nagaschuppen der Hasskämme.";
		};
		[2877] = {
		   ["name"] = "Den Lauerfels aufräumen";
		   ["objective"] = "Tötet 10 grüne Schlicke sowie 10 jadegrüne Schlamme und meldet Euch dann wieder bei Fraggar Donnermantel beim Nistgipfel.";
		};
		[5801] = {
		   ["name"] = "Feuersäulen geschmiedet";
		   ["objective"] = "Bringt die Dietrichform und 2 Barren Thorium zur Spitze des Feuersäulengrats im Krater von Un'Goro. Benutzt die Dietrichform am Lavasee, um den unvollendeten Dietrich zu schmieden.$B$BBringt den unvollendeten Dietrich dann zum Alchemisten Arbington an der Zugwindspitze in den Westlichen Pestländern.";
		};
		[2925] = {
		   ["name"] = "Klockmorts Grundlagen";
		   ["objective"] = "Sprecht mit Klockmort Spannsplint in Eisenschmiede.";
		};
		[2933] = {
		   ["name"] = "Giftflaschen";
		   ["objective"] = "Bringt eine Giftflasche zu einem Apotheker nach Tarrens Mühle.";
		};
		[2941] = {
		   ["name"] = "Der Borger";
		   ["objective"] = "Bringt den Brief zu Curgle Kurbelhüpf nach Tanaris.";
		};
		[2949] = {
		   ["name"] = "Die Rückkehr des Rings";
		   ["objective"] = "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist.";
		};
		[5929] = {
		   ["name"] = "Großer Bärengeist";
		   ["objective"] = "Sucht den großen Bärengeist im nordwestlichen Teil der Mondlichtung auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Sternenschauer nach Nachthafen auf der Mondlichtung zurück.";
		};
		[2973] = {
		   ["name"] = "Schimmer für einen neuen Umhang";
		   ["objective"] = "Bringt 10 regenbogenfarbene Grimmlingflitzerflügel zu Krueg Schädelspalter nach Camp Mojache.";
		};
		[2981] = {
		   ["name"] = "Eine Bedrohung in Feralas";
		   ["objective"] = "Belgrom Felshammer will, dass Ihr mit Rok Orhan im Camp Mojache sprecht.";
		};
		[2989] = {
		   ["name"] = "Der Altar von Zul";
		   ["objective"] = "Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Krallenaxt zurück.";
		};
		[2997] = {
		   ["name"] = "Foliant der Offenbarung";
		   ["objective"] = "Sprecht mit Tiza Kriegshammer in Eisenschmiede.";
		};
		[6025] = {
		   ["name"] = "Offene Rechnungen";
		   ["objective"] = "Geht nach Herdweiler, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Grubenschatten in den Westlichen Pestländern zurück.";
		};
		[6041] = {
		   ["objective"] = "Reist in den Pestwald, nordwestlich der Kapelle des Hoffnungsvollen Lichts. Zerstört 8 Geißelbauwerke, indem Ihr Smokeys spezielles Präparat am Mal der Zerstörung in jedem Bauwerk benutzt. Smokey hat die Ziggurats und Schlachthäuser markieren lassen.$B$BWenn Ihr die Bombe gelegt habt, dann verlasst das Bauwerk und staunt über Euer Geschick.$B$BÜbrigens, Smokeys spezielles Präparat ist recht...instabil.";
		   ["name"] = "When Smokey Sings, I Get Violent";
		};
		[6073] = {
		   ["name"] = "Der Weg des Jägers";
		   ["objective"] = "Sprecht mit Dazalar in Dolanaar in Teldrassil.";
		};
		[6089] = {
		   ["name"] = "Die Ausbildung des Tiers";
		   ["objective"] = "Sprecht mit Holt Donnerhorn auf der Anhöhe der Jäger in Donnerfels.";
		};
		[6121] = {
		   ["name"] = "Neue Lektionen";
		   ["objective"] = "Reist zur Mondlichtung und sprecht mit Dendrite Sternenschauer im Dorf Nachthafen.";
		};
		[8241] = {
		   ["name"] = "Nachschub an feurigem Fluxus: Eisen";
		};
		[8273] = {
		   ["name"] = "Orans Dankbarkeit";
		};
		[3101] = {
		   ["name"] = "Geweihter Brief";
		   ["objective"] = "Lest den geweihten Brief und sprecht mit Bruder Sammuel in der Abtei von Nordhain.";
		};
		[3109] = {
		   ["name"] = "Verschlüsselte Rune";
		   ["objective"] = "Lest die verschlüsselte Rune und sprecht mit Solm Hargrin im Ambossar.";
		};
		[8369] = {
		   ["name"] = "Die Invasoren des Alteractals";
		   ["objective"] = "Bringt 3 Ehrenabzeichen des Alteractals zu einem der Kriegshetzer der Horde, außerhalb der Schlachtfelder.";
		};
		[3125] = {
		   ["name"] = "Muisek von Feendrachen";
		   ["objective"] = "Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus. Benutzt das Muisekgefäß, um die gefallenen Feendrachen zu schrumpfen und einzufangen.";
		};
		[8433] = {
		   ["name"] = "Schlacht der Kriegshymnenschlucht";
		};
		[6281] = {
		   ["name"] = "Weiter nach Sturmwind";
		   ["objective"] = "Bucht einen Greifenritt bei Greifenmeister Thor, dann bringt Lewis' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in der Altstadt von Sturmwind.";
		};
		[8497] = {
		   ["name"] = "Wüstenüberlebenspaket";
		   ["objective"] = "Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 geräucherte Wüstenknödel zu Calandrath in der Taverne von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz I, um diese Aufgabe abschließen zu können.";
		};
		[8529] = {
		   ["name"] = "Die Allianz braucht mehr Tüpfelgelbschwänze!";
		   ["objective"] = "Bringt 20 Tüpfelgelbschwänze zu Jägerin Flinkbach beim Landeplatz in Dun Morogh.";
		};
		[8561] = {
		   ["name"] = "Krone des Eroberers";
		   ["objective"] = "Bringt Vek'nilashs Reif, 2 Götzen der Sonne, 5 Steinskarabäen und 5 Kristallskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.";
		};
		[8593] = {
		   ["name"] = "Beinkleider des Orakels";
		   ["objective"] = "Bringt Ouros intakte Haut, 2 Götzen des Lebens, 5 Goldskarabäen und 5 Tonskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.";
		};
		[8625] = {
		   ["name"] = "Schulterpolster des Mysteriums";
		   ["objective"] = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen des Todes, 5 Steinskarabäen und 5 Bronzeskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.";
		};
		[8657] = {
		   ["name"] = "Diadem des Hetzers";
		   ["objective"] = "Bringt Vek'lors Diadem, 2 Götzen des Kampfes, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.";
		};
		[8689] = {
		   ["name"] = "Schleier der unendlichen Weisheit";
		   ["objective"] = "Bringt 1 Kampftuch der Qiraji, 2 Jaspisgötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.";
		};
		[8721] = {
		   ["name"] = "Urahnin Sternenweber";
		};
		[8753] = {
		   ["name"] = "Der Pfad des Eroberers";
		};
		[6441] = {
		   ["name"] = "Satyrhörner";
		   ["objective"] = "Sammelt für Pixel im Splitterholzposten 16 Satyrhörner.";
		};
		[8817] = {
		   ["name"] = "Ein Belobigungsabzeichen";
		};
		[8849] = {
		   ["name"] = "Zwanzig Abzeichen gegen Kriegsmaterial tauschen";
		};
		[8881] = {
		   ["name"] = "Große Raketenbündel";
		};
		[8913] = {
		   ["name"] = "Ein aufrichtiges Angebot";
		   ["objective"] = "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Wildherzens zu Mokvar in Orgrimmar zurück.";
		};
		[6521] = {
		   ["name"] = "Eine unheilige Allianz";
		   ["objective"] = "Bringt den Kopf von Botschafter Malcin zu Bragor Blutfaust nach Unterstadt.";
		};
