		   ["name"] = "Das Beste gibt's zum Schluss";
		   ["objective"] = "Gebt Mokvar Eure Krone des Gläubigen und Eure Robe des Gläubigen.";
		};
		[9041] = {
		   ["name"] = "Taillenschutz des Schreckenspanzers";
		   ["objective"] = "Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Taillenschutz des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Taillenschutz, 8 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.";
		};
		[9073] = {
		   ["name"] = "Handschützer des Erdspalters";
		   ["objective"] = "Rimblat Erdspalter bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Handschützer des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Handschützer, 8 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.";
		};
		[3301] = {
		   ["name"] = "Mura Runentotem";
		   ["objective"] = "Sprecht mit Mura Runentotem im Grabmal im Silberwald.";
		};
		[9137] = {
		   ["name"] = "Wildwedel";
		};
		[9201] = {
		   ["name"] = "Handwerksverfügung - Großer Arkanschutztrank";
		   ["objective"] = "Bringt 15 große Arkanschutztränke und die Handwerksverfügung für die großen Arkanschutztränke zu Rottenkommandant Steinberster bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.";
		};
		[9233] = {
		   ["name"] = "Omarions Leitfaden";
		   ["objective"] = "Bringt Omarions Leitfaden zu Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.";
		};
		[6681] = {
		   ["objective"] = "Bringt das Siegel von Rabenholdt zu Fahrad im Rabenholdtanwesen, das versteckt in den Hügeln des Hügellands liegt.$B$BUnterwegs wird man Eure Schlauheit testen. Seid darauf gefasst.";
		   ["name"] = "Das Anwesen, Rabenholdt";
		};
		[3365] = {
		   ["name"] = "Den Becher zurückbringen";
		   ["objective"] = "Bringt Nori Stolzmut im Eisklammtal den Becher zurück.";
		};
		[3373] = {
		   ["name"] = "Die Essenz des Eranikus";
		   ["objective"] = "Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet.";
		};
		[6761] = {
		   ["name"] = "Die neue Grenze";
		   ["objective"] = "Sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius von Darnassus.";
		};
		[6825] = {
		   ["name"] = "Ruf der Lüfte - Guses Luftflotte";
		};
		[3421] = {
		   ["name"] = "Rückreise";
		};
		[3445] = {
		   ["name"] = "Der Versunkene Tempel";
		   ["objective"] = "Sucht Marvon Nietensucher in Tanaris.";
		};
		[3453] = {
		   ["name"] = "Die Fackel der Vergeltung";
		   ["objective"] = "Wartet bis Kalaran Windklinge die Fackel der Vergeltung vollendet hat.";
		};
		[6921] = {
		   ["name"] = "Inmitten der Ruinen";
		   ["objective"] = "Bringt den Tiefenkern zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental.";
		};
		[6985] = {
		   ["name"] = "Vorräte der Eisenschachtmine";
		   ["objective"] = "Bringt 10 Vorräte der Eisenschachtmine zum Rüstmeister der Horde in die Burg Frostwolf.";
		};
		[7001] = {
		   ["name"] = "Verwaiste Ställe";
		   ["objective"] = "Findet einen Frostwolf im Alteractal. Wenn Ihr Euch in der Nähe eines Frostwolfs befindet, benutzt den Frostwolfmaulkorb um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Frostwolf bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden.";
		};
		[3509] = {
		   ["name"] = "Der Name der Bestie";
		   ["objective"] = "Sprecht mit Lord Arkkoroc in Azshara. Beginnt Eure Suche am Rand des Wassers, um den Tempel von Arkkoran zu finden.";
		};
		[3517] = {
		   ["name"] = "Wissen stehlen";
		   ["objective"] = "Sucht die Schrifttafel von Beth'Amara, die Schrifttafel von Jin'yael, die Schrifttafel von Markri und die Schrifttafel von Sael'hai, bevor Ihr zu Jediga in Azshara zurückkehrt.";
		};
		[3525] = {
		   ["name"] = "Ausschalten des Götzen";
		   ["objective"] = "Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln der Klingenhauer.$B$BBeschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten.";
		};
		[7065] = {
		   ["name"] = "Verderbnis von Erde und Samenkorn";
		   ["objective"] = "Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück.";
		};
		[7081] = {
		   ["objective"] = "Erobert einen Friedhof und kehrt zu Unteroffizier Durgen Sturmlanze im Alteracgebirge zurück.";
		   ["name"] = "Die Friedhöfe im Alteractal";
		};
		[3565] = {
		   ["name"] = "Xylems Bezahlung für Jediga";
		   ["objective"] = "Bringt Xylems Notiz zu Jediga in Azshara.";
		};
		[7161] = {
		   ["name"] = "Flaggenjagd";
		   ["objective"] = "Begebt Euch in die Höhle der Wildpfoten südöstlich vom Hauptstützpunkt und findet das Banner der Frostwölfe. Bringt anschließend Kriegsmeister Laggrond das Banner.";
		};
		[7241] = {
		   ["name"] = "Die Verteidigung der Frostwölfe";
		   ["objective"] = "Reist ins Alteractal im Vorgebirge des Hügellands. Sucht dort Kriegsmeister Laggrond auf und beginnt Eure Karriere als Soldat der Frostwölfe.";
		};
		[3629] = {
		   ["name"] = "Gobliningenieurskunst";
		   ["objective"] = "Wenn Ihr etwas über die Gobliningenieurskunst erlernen wollt, dann bringt das Handbuch der Ingenieurskunstdisziplinen zu Nixx Sprossfeder nach Gadgetzan.";
		};
		[3637] = {
		   ["name"] = "Gnomeningenieurskunst";
		   ["objective"] = "Wenn Ihr mehr über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Glotz Widrikus nach Beutebucht.";
		};
		[3645] = {
		   ["name"] = "Mitgliedskarten-Erneuerung";
		};
		[7321] = {
		   ["name"] = "Milde Schildkrötensuppe";
		   ["objective"] = "Bringt 10 Stücke Schildkrötenfleisch zu Christoph Jeffkott in Tarrens Mühle.";
		};
		[7385] = {
		   ["name"] = "Eine Gallone Blut";
		};
		[3701] = {
		   ["objective"] = "Begebt Euch zu den Ruinen von Thaurissan in der Brennenden Steppe und sammelt Informationen über die Relikte von Thaurissan. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt.";
		   ["name"] = "Die glimmenden Ruinen von Thaurissan";
		};
		[7481] = {
		   ["name"] = "Elfische Legenden";
		   ["objective"] = "Sucht in Düsterbruch nach Kariel Winthalus. Meldet Euch anschließend bei dem Weisen Korolusk in Camp Mojache.";
		};
		[7497] = {
		   ["name"] = "Die Reise beginnt erst";
		};
		[3765] = {
		   ["name"] = "Verderbnis in der Fremde";
		   ["objective"] = "Reist zu Gershala Nachtraunen in Auberdine.";
		};
		[3781] = {
		   ["name"] = "Morgenkornforschung";
		   ["objective"] = "Bringt den Samenkorngutschein des Erzdruiden zu Mathrengyl Bärenfährte in der Enklave des Cenarius von Darnassus.";
		};
		[3789] = {
		   ["name"] = "Erzdruide Hirschhaupt helfen";
		   ["objective"] = "Sprecht mit Erzdruide Fandral Hirschhaupt in Darnassus.";
		};
		[7625] = {
