		};
		[8692] = {
		   ["name"] = "Umhang des endlosen Lebens";
		   ["objective"] = "Bringt 1 Hoheitstuch der Qiraji, 2 Zinnobergötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.";
		};
		[4363] = {
