		   ["objective"] = "Gebt Deliana Eure Maske der Furcht und Eure Robe der Furcht.";
		};
		[9044] = {
		   ["name"] = "Beinschützer der Erlösung";
		   ["objective"] = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Beinschützer der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinschützer, 20 kampfzerschlissene Plattenstücke, 4 Arkanitbarren und 2 Nexuskristalle.";
		};
		[9108] = {
		   ["name"] = "Handschuhe des verseuchten Herzens";
		   ["objective"] = "Mataus der Zornwirker bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Handschuhe des verseuchten Herzens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Handschuhe, 8 kampfzerschlissene Stoffstücke und 4 Einheiten Mondstoff.";
		};
		[4603] = {
		   ["name"] = "Funkelmatastisch";
		};
		[9236] = {
		   ["name"] = "Eisfluchbrustplatte";
		   ["objective"] = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 8 gefrorene Runen, 16 Thoriumbarren, 2 Arkanitbarren, 4 Essenzen des Wassers und 300 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein.";
		};
