		};
		[8341] = {
		   ["name"] = "Lords des Rates";
		   ["objective"] = "Bringt Aurel Goldblatt auf Burg Cenarius 5 große glänzende Splitter und 3 abyssische Siegel.";
		};
		[8373] = {
		   ["name"] = "Die Kraft der Pinie";
		   ["objective"] = "Verwendet einen Stinkbombenreiniger, um alle Stinkbomben der Verlassenen zu vernichten, die hier in Süderstade losgelassen wurden. Kehrt zu Unteroffizier Hartman in Süderstade zurück, wenn Ihr fertig seid.";
		};
