		[9084] = {
		   ["name"] = "Armschienen der Knochensense";
		   ["objective"] = "Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Armschienen der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Armschienen, 6 kampfzerschlissene Lederstücke, 1 Arkanitbarren, 2 geschmeidige unverwüstliche Bälge und 10 Goldstücke.";
		};
		[9116] = {
