		};
		[6146] = {
		   ["name"] = "Nathanos' List";
		   ["objective"] = "Reist nach Tyrs Hand, südöstlich der Siedlung Marris. Dort angekommen beißt in den faulen Apfel. In der Verkleidung des Scharlachroten Kreuzzugs überbringt Ihr Lord Valdelmar den Befehl des Obersten Kreuzfahrers.";
		};
		[5146] = {
		   ["name"] = "Elementarlederverarbeitung";
		   ["objective"] = "Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Brumn Winterhuf in den Arathibergen.$B$BWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.$B$BWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.";
		};
		[9244] = {
		   ["name"] = "Eisschuppenarmschienen";
		   ["objective"] = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 4 gefrorene Runen, 16 schwere Skorpidschuppen, 5 Essenzen des Wassers, 3 geschmeidige unverwüstliche Bälge und 200 Gold.";
		};
