		[5023] = {
		   ["name"] = "Besser spät als nie";
		   ["objective"] = "Wendet Euch an die königlichen Vorarbeiter von Unterstadt, um etwas über den Aufenthaltsort von Jeremiah Teufelsstein herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter in der Nähe der Gilden- und Wappenrock-Registrierung.";
		};
		[2520] = {
		   ["name"] = "Sathrahs Opferung";
		   ["objective"] = "Priesterin A'moora möchte, dass Ihr Lady Sathrahs silbrige Spinndrüsen am Brunnen innerhalb des Tempels ablegt und dann zu ihr zurückkehrt.";
		};
		[5055] = {
		   ["name"] = "Brumeran von den Eiswindschimären";
		   ["objective"] = "Storm Schattenhuf in der Ewigen Warte in Winterquell möchte, dass Ihr Brumeran tötet.";
		};
