		   ["name"] = "Tabethas Aufgabe";
		   ["objective"] = "Sprecht mit Tabetha in den Düstermarschen.";
		};
		[5087] = {
		   ["name"] = "Läufer der Winterfelle";
		   ["objective"] = "Sucht die Läufer der Winterfelle und hindert sie daran, ihre Lieferung zum Lager der Winterfelle zu bringen.";
		};
		[5103] = {
		   ["name"] = "Heißer, feuriger Tod";
		   ["objective"] = "Jemand auf dieser Welt muss doch wissen, was mit diesen Stulpen zu tun ist. Viel Glück!";
		};
		[2761] = {
		   ["name"] = "Hier verhütten, da verhütten";
		   ["objective"] = "Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 40 Eisenbarren.";
		};
		[9051] = {
		   ["name"] = "Giftexperiment";
		   ["objective"] = "Stecht einen Teufelssaurier mit dem Teufelssaurierhaken und kehrt danach zu Torwa Pfadfinder im Krater von Un'Goro zurück.";
		};
		[5151] = {
		   ["name"] = "Hyperkondensator-Dingsda";
		   ["objective"] = "Erschlagt die Bestie und bringt den Hyperkondensator sowie den Pantherkäfigschlüssel zu Wizlo Lagerputzer zurück.";
		};
		[5167] = {
		   ["name"] = "Beinplatten des chromatischen Widersetzers";
		   ["objective"] = "Um die Beinplatten des chromatischen Widersetzers zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:$B$B1 chromatischer Knochenpanzer.$B$B10 glänzende chromatische Schuppen.$B$B10 Einheiten Blut von Helden.$B$B5 Häute des Schattens.";
		};
		[6846] = {
		   ["name"] = "Der Angriff soll beginnen!";
		};
		[1656] = {
		   ["name"] = "Eine unvollendete Aufgabe";
		   ["objective"] = "Bringt das Bündel Felle zu Gastwirt Kauth ins Dorf der Bluthufe.";
		};
		[2608] = {
		   ["name"] = "Die Berührung von Zanzil";
		   ["objective"] = "Ihr solltet Euch /hinlegen, damit Dok Mixilpixil Euch untersuchen kann. Denn wie soll er ein Heilmittel finden, wenn er die Ursache nicht finden kann?";
		};
		[5231] = {
		   ["name"] = "Ziel: Dalsons Tränenfeld";
		   ["objective"] = "Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.";
		};
		[5247] = {
		   ["name"] = "Fragmente der Vergangenheit";
		   ["objective"] = "Bringt einen verzauberten Thoriumbarren, 5 Kristallflicker und eine Phiole mit Düsterwasser zu Aurora Himmelsrufer beim Nordpassturm in den Östlichen Pestländern.";
		};
		[5263] = {
		   ["name"] = "Übertroffen";
		   ["objective"] = "Zieht nach Stratholme und vernichtet Baron Totenschwur. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück.";
		};
		[5519] = {
		   ["name"] = "Der Ogeranzug der Gordok";
		};
		[8970] = {
		   ["name"] = "Ich sehe die Insel Alcaz in Eurer Zukunft";
		   ["objective"] = "Bringt Bodley im Schwarzfels 20 Einheiten Bluttang von den Naga der Strashaz.";
		};
		[7645] = {
		   ["name"] = "Mit Manna angereichertes Pferdefutter";
		   ["objective"] = "Treibt 20 angereicherte Mannakekse - die ausschlaggebende Zutat für die Herstellung von mit Manna angereichertem Pferdefutter - für Merideth Carlson aus Süderstade im Vorgebirge des Hügellands auf. Die Argentumdämmerung ist als alleiniger Händler dieser Kekse bekannt.$B$BZusätzlich müsst Ihr ihre Gefühle noch mit 50 Goldstücken besänftigen.";
		};
		[7761] = {
		   ["name"] = "Schwarzfausts Befehl";
		   ["objective"] = "Das war ja vielleicht mal ein dummer Orc. Es sieht so aus, als müsstet Ihr dieses Brandzeichen finden, um an das Mal von Drakkisath zu gelangen. Damit sollte sich die Befehlskugel aktivieren lassen.$B$BDem Brief zufolge, wird das Brandzeichen von General Drakkisath bewacht. Vielleicht solltet Ihr diesem Hinweis nachgehen.";
		};
		[5343] = {
		   ["name"] = "Das Familienvermögen der Barovs";
		   ["objective"] = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Darrowehr, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Süderstade. Kehrt zu Weldon Barov zurück, sobald die Aufgabe erledigt ist.";
		};
		[1185] = {
		   ["name"] = "Unter dem Chitin war...";
		};
