		   ["name"] = "Der azurblaue Schlüssel";
		   ["objective"] = "Bringt den azurblauen Schlüssel zu Lord Jorach Rabenholdt.";
		};
		[9246] = {
		   ["name"] = "Eisschuppenbrustplatte";
		   ["objective"] = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 8 gefrorene Runen, 24 schwere Skorpidschuppen, 7 Essenzen des Wassers, 5 geschmeidige unverwüstliche Bälge und 300 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein.";
		};
