		};
		[7647] = {
		   ["name"] = "Gerechtigkeit und Erlösung";
		   ["objective"] = "Benutzt das Orakel der Anrufung im Herzen des Kellergewölbes des Großen Ossuariums in Scholomance. Damit ruft Ihr die verfluchten Geister, über deren Schicksal Ihr richten müsst. Durch das Besiegen der Geister wird der Todesritter Schattensichel beschworen. Besiegt ihn und holt Euch die verlorene Seele des gefallenen Streitrosses.$B$BGebt die Seele des gefallenen Streitrosses und das gesegnete und verzauberte Pferdegeschirr Schattensichels gefallenem Streitross zurück.";
		};
		[6185] = {
		   ["name"] = "Die Östlichen Pestländer";
		   ["objective"] = "Sucht in den Östlichen Pestländern nach Hinweisen auf den 'Pestrufer' und die vermissten SI:7-Agenten. Wenn Ihr SI:7-Insignien findet, bringt sie zu Flint Schattenmoor an der Zugwindspitze.";
		};
		[1386] = {
		   ["name"] = "Angriff auf die Kolkar";
		   ["objective"] = "Haltet Euren Ruf bei den Magram aufrecht. Tötet 12 Zentauren der Kolkar, 12 Späher der Kolkar sowie 6 Raufer der Kolkar und kehrt dann zu Warug ins Magramdorf in Desolace zurück.";
		};
		[4185] = {
		   ["name"] = "Die wahren Meister";
		   ["objective"] = "Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon.";
		};
