		[8306] = {
		   ["objective"] = "Kommandant Mar'alith auf Burg Cenarius in Silithus möchte, dass Ihr seine geliebte Natalia wiederfindet. Die von Euch gesammelten Informationen deuten darauf hin, dass Ihr sie im Bau des Regalschwarms im Süden finden könntet.$B$BSprecht noch einmal mit den Zwergen in Bronzebarts Lager, bevor Ihr Euch in den Schwarmbau begebt. Ihr Wissen könnte sich als hilfreich erweisen und sicherlich, haben sie noch einige Aufgaben für Euch.$B$BUnd $n, denkt an die Worte des Kommandanten: \"Tut, was Ihr tun müsst...\"";
		   ["name"] = "Der Schlund des Wahnsinns";
		};
		[8322] = {
		   ["name"] = "Faule Eier";
		   ["objective"] = "Werft die faulen Eier in die großen Braufässchen im Gasthaus von Süderstade.";
		};
		[5862] = {
		   ["name"] = "Scharlachrote Täuschung";
		   ["objective"] = "Sprecht mit Myranda, um die Scharlachrote Illusion zu erhalten. Begebt Euch nach Herdweiler, während Ihr unter dem Einfluss der Scharlachroten Illusion steht, und übergebt dem Hochlord Taelan Fordring Tirions Geschenk.$B$BHerdweiler liegt im Norden, Taelan dürfte sich in der Burg Mardenholde aufhalten.";
		};
		[5344] = {
		   ["name"] = "Der letzte Barov";
		   ["objective"] = "Begebt Euch zum Bollwerk - Territorium der Horde - und ermordet Alexi Barov. Nehmt seinen Kopf und kehrt zu Weldon Barov zurück.$B$BSeid gewarnt, Alexi wird wahrscheinlich gut durch Abschaum der Horde geschützt.";
		};
		[9111] = {
		   ["name"] = "Robe des Glaubens";
		   ["objective"] = "Vater Inigo Montoy bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Robe des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Robe, 25 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.";
		};
